// ============================================================
// Tc2_Utilities.UInt64Mul64Ex 演示程序（FUNCTION，单周期触发）
// ============================================================
// 场景：计算累计扭矩 × 累计转角，结果可能超 64 位，需溢出报警。
// 价值：替代手写'先转 LREAL 估算溢出再走整数路径'的判断；一次调用拿乘积 + 溢出位。
// 验证步骤：
//   1. 把本 PROGRAM 加到 PlcTask 调用列表
//   2. 编译 + 登录
//   3. 在线把 b... 触发位置 TRUE 一个周期
//   4. 观察输出变量是否符合期望
// ============================================================

bOverflow := FALSE;                                    // 每周期先清零
IF bCompute THEN
    uliWork := UInt64Mul64Ex(uliTorque, uliAngle, bOverflow);
    IF bOverflow THEN
        // 工程响应：饱和并触发上层报警
        uliWork := ULARGE_INTEGER(16#FFFFFFFF, 16#FFFFFFFF);
    END_IF;
    bCompute := FALSE;
END_IF;
